-- 2026 workbook cost backfill. Source: "2026 (new) Damage Master (1).xlsx",
-- Cost column on every location sheet, keyed by that sheet's JOT#.
--
-- WHY: the JotForm claim seed never wrote a cost and phase 2 applied status
-- and lifecycle_state only, so 278 of 325 Closed — Paid claims carry no dollar
-- figure at all. The workbook has always had it; this moves it into D1.
--
-- Run the two SELECTs first. The UPDATE only ever fills a NULL — it will not
-- overwrite an amount the live approval flow set.

DROP TABLE IF EXISTS _wb_cost;
CREATE TABLE _wb_cost (jot TEXT PRIMARY KEY, cost REAL NOT NULL);

